,    (gen_random_uuid(), v_lesson_id, 'user_side', 'Memorizing Facts', NOW(), NOW())
,    (gen_random_uuid(), v_lesson_id, 'ai_side', 'Deep Understanding', NOW(), NOW())
,    (gen_random_uuid(), v_lesson_id, 'content', 'Deep understanding lets you solve new problems, while memorized facts can be quickly forgotten.
